R,C=26,29
pts={0:[2],4:[3,5],5:[16],6:[18],7:[15],8:[5],9:[16],10:[25],11:[0,16],12:[6],13:[12],14:[20,24],16:[6],17:[14,17],18:[13],19:[14,27],20:[21],22:[22,28],25:[8]}
grid=[[2]*C for _ in range(R)]
for r,cs in pts.items():
 for c in cs:grid[r][c]=6
# fill horizontal spans
for r,cs in pts.items():
 if len(cs)>1:
  for c in range(min(cs)+1,max(cs)):
   if grid[r][c]==2:grid[r][c]=3
# vertical spans by columns
cols={c:[] for c in range(C)}
for r,cs in pts.items():
 for c in cs:cols[c].append(r)
for c,rs in cols.items():
 if len(rs)>1:
  for r in range(min(rs)+1,max(rs)):
   if grid[r][c]==2:grid[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in grid))
